def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if abs(shift) > n:
        return s[::-1]
    shift = shift % n  # normalize shift within length
    if shift >= 0:
        # positive shift: shift digits to the left
        return s[shift:] + s[:shift]
    else:
        # negative shift: shift digits to the right
        shift = -shift
        return s[-shift:] + s[:-shift]


