def anti_shuffle(s):
    import re
    # Split on spaces, but keep spaces as separate tokens
    tokens = re.split(r'(\s+)', s)
    result = []
    for token in tokens:
        if token.isspace() or token == '':
            result.append(token)
        else:
            # Sort all characters in the token ascending by ASCII
            sorted_token = ''.join(sorted(token))
            result.append(sorted_token)
    return ''.join(result)


