def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    if n == 1:
        return True

    def is_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    def is_non_increasing(a):
        return all(a[i] >= a[i+1] for i in range(len(a)-1))

    # Try all right shifts (0 to n-1)
    for shift in range(n):
        rotated = arr[-shift:] + arr[:-shift]
        if is_non_decreasing(rotated) or is_non_increasing(rotated):
            return True
    return False


