from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    # Split the input into groups
    groups = paren_string.split()

    # For each group, compute the max depth using accumulate and max without loops/recursion
    # Use map with a lambda for each group
    # Depth is increased by '(' and decreased by ')'
    # max depth is max of prefix sums of +1 for '(' and -1 for ')'

    from itertools import accumulate

    def max_depth(group: str) -> int:
        steps = map(lambda c: 1 if c == '(' else -1, group)
        return max(accumulate(steps), default=0)

    return list(map(max_depth, groups))


