from collections import Counter

def parse_music(music_string: str) -> Tuple[List[int], str]:
    notes = music_string.split()
    beats_map = {'o': 4, 'o|': 2, '.|': 1}
    beats = list(map(beats_map.get, notes))

    count = Counter(notes)
    max_freq = max(count.values())
    candidates = [note for note, freq in count.items() if freq == max_freq]
    # Among tied candidates, pick one with longest beat
    most_common_note = max(candidates, key=lambda n: beats_map[n])

    return beats, most_common_note


