def triples_sum_to_zero(l):
    nums = list(map(int, l))
    n = len(nums)
    for i in range(n - 2):
        seen = set()
        for j in range(i + 1, n):
            complement = - (nums[i] + nums[j])
            if complement in seen:
                return True
            seen.add(nums[j])
    return False


