from collections import Counter

def search(lst):
    # Count frequencies (works for hashable elements including strings)
    freq = Counter(lst)
    keys = freq.keys()

    # If all elements are strings, return the lex greatest string
    if all(isinstance(k, str) for k in keys):
        return max(keys)

    # Otherwise, filter keys to positive integers only
    positive_ints = [k for k in keys if isinstance(k, int) and k > 0]

    # Among positive integers, find those with freq >= value
    candidates = [k for k in positive_ints if freq[k] >= k]

    if not candidates:
        return -1
    return max(candidates)


