def total_match(lst1, lst2):
    if not lst1 and not lst2:
        return []
    # Check if either list contains strings
    str1 = any(isinstance(x, str) for x in lst1)
    str2 = any(isinstance(x, str) for x in lst2)
    # If any list contains strings, return the longest string among all strings in both lists
    if str1 or str2:
        strings = [x for x in lst1 + lst2 if isinstance(x, str)]
        if not strings:
            return []
        longest = max(strings, key=len)
        return longest
    # Otherwise, both lists contain only integers (or empty)
    # Calculate total digits in each list
    # digits in a number = len(str(abs(num)))
    total_digits1 = sum(len(str(abs(x))) for x in lst1)
    total_digits2 = sum(len(str(abs(x))) for x in lst2)
    # If total digits are equal, return first list
    if total_digits1 <= total_digits2:
        res = lst1
    else:
        res = lst2
    # Sort ascending but maintain original order among equals
    # This is the definition of a stable sort, so normal sorted() suffices
    # The phrase "at the same time maintain its original order" means stable sort
    # So just do sorted(res), which is stable, and done
    sorted_res = sorted(res)
    return ' '.join(str(x) for x in sorted_res)


