def move_one_ball(arr):
    if not arr:
        return True

    def is_sorted(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    n = len(arr)
    # Since no loops allowed, we use recursion to check each shift
    def check_shifts(shift):
        if shift == n:
            return False
        # Right shift by 'shift' means last 'shift' elements come to front
        shifted = arr[-shift:] + arr[:-shift] if shift > 0 else arr
        if is_sorted(shifted):
            return shift
        else:
            return check_shifts(shift+1)

    return check_shifts(0)


