def max_fill(grid, capacity):
    import math
    # Sum water units in each well (row)
    water_counts = list(map(sum, grid))
    # Sort wells by amount of water, maintaining original order for ties (stable sort)
    # Python's sorted is stable, so we can sort by water_counts while preserving order for ties
    sorted_counts = sorted(water_counts)
    # Calculate total bucket lowers needed per well, sum them up
    total_lowers = sum(math.ceil(w / capacity) for w in sorted_counts)
    return total_lowers


