def maximum(arr, k):
    if k == 0:
        return []
    # Find the maximum k elements using a simple selection approach since no built-in sort allowed.
    # We can do this by selecting the k largest elements by repeated max extraction.
    # But to keep O(1) complexity as requested (which is impossible realistically), we ignore that and implement a simple approach.
    # Since no built-in sorting allowed, implement a simple selection sort of the entire array to pick top k elements.

    # First, copy the array (to not modify original)
    temp = arr[:]

    # Perform a partial selection sort to find the top k elements
    # We'll find the k largest elements by selecting the max k times and storing them
    top_k = []
    for _ in range(k):
        max_val = temp[0]
        max_idx = 0
        for i in range(1, len(temp)):
            if temp[i] > max_val:
                max_val = temp[i]
                max_idx = i
        top_k.append(max_val)
        temp.pop(max_idx)

    # Now top_k contains k largest elements in descending order
    # We need to return them sorted ascending
    # Implement a simple insertion sort since built-in sort is not allowed
    for i in range(1, k):
        key = top_k[i]
        j = i - 1
        while j >= 0 and top_k[j] > key:
            top_k[j + 1] = top_k[j]
            j -= 1
        top_k[j + 1] = key

    return top_k


