def digits(n):
    s = str(n)
    odd_digits = [int(d) for d in s if int(d) % 2 == 1]
    even_digits = [int(d) for d in s if int(d) % 2 == 0]
    if not odd_digits or not even_digits:
        return 0
    from functools import reduce
    from operator import mul
    odd_product = reduce(mul, odd_digits, 1)
    even_product = reduce(mul, even_digits, 1)
    return str(odd_product) if isinstance(n, str) else even_product


