from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    result = []
    groups = paren_string.split()
    for group in groups:
        if not group:
            continue
        depth = 0
        max_depth = 0
        valid = True
        for ch in group:
            if ch == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif ch == ')':
                depth -= 1
                if depth < 0:
                    valid = False
                    break
            else:
                # invalid character, treat as invalid group
                valid = False
                break
        if valid and depth == 0:
            result.append(max_depth)
    return result


