def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Check if already sorted
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Find the index where the array "breaks" the sorted order
    # There should be at most one such break for the array to be a rotated sorted array.
    break_points = [i for i in range(n-1) if arr[i] > arr[i+1]]

    # If no break points, array is sorted (already handled above), but for safety:
    if not break_points:
        return True

    # If more than one break point, cannot be sorted by rotation
    if len(break_points) > 1:
        return False

    # If exactly one break point at index i, check if the array can be rotated to sorted
    i = break_points[0]
    # After rotation, the array should be sorted:
    # Check if last element <= first element (to complete rotation)
    return arr[-1] <= arr[0]


