def move_one_ball(seq):
    if not seq:
        return True
    n = len(seq)
    # Since values are distinct, a sorted non-decreasing sequence is strictly increasing.
    # Check how many "drops" (where seq[i] > seq[i+1]) appear in the circular sequence.
    drops = 0
    for i in range(n):
        if seq[i] > seq[(i + 1) % n]:
            drops += 1
            if drops > 1:
                return False
    return True


