from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        balanced = True
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
                if current_depth < 0:
                    balanced = False
                    break
            else:
                # invalid character, consider unbalanced
                balanced = False
                break
        if balanced and current_depth == 0:
            result.append(max_depth)
        else:
            # If unbalanced, per rule 3, treat as zero depth
            result.append(0)
    return result


