def triples_sum_to_zero(l: list):
    """
    Returns True if there exist three distinct elements in l whose sum is zero.
    Otherwise returns False.
    """
    n = len(l)
    l.sort()
    for i in range(n):
        # Avoid duplicates for the first element
        if i > 0 and l[i] == l[i-1]:
            continue
        target = -l[i]
        left, right = i + 1, n - 1
        while left < right:
            current_sum = l[left] + l[right]
            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    return False


