def circular_shift(x, shift):
    s = str(abs(x))
    n = len(s)
    if n == 0:
        return s
    shift %= n
    if shift == 0:
        return s
    if shift > 0:
        return s[-shift:] + s[:-shift]
    else:
        shift = -shift
        return s[shift:] + s[:shift]


