def move_one_ball(arr):
    if not arr:
        return True
    sorted_arr = sorted(arr)
    n = len(arr)
    # Check if arr is a right rotation of sorted_arr
    # Right rotation by k means arr[i] == sorted_arr[(i - k) % n]
    # Try all k from 0 to n-1
    for k in range(n):
        if all(arr[i] == sorted_arr[(i - k) % n] for i in range(n)):
            return True
    return False


