def monotonic(l: list):
    if len(l) < 2:
        return True
    direction = 0  # 0: unknown, 1: increasing, -1: decreasing
    for i in range(1, len(l)):
        if l[i] > l[i-1]:
            if direction == -1:
                return False
            direction = 1
        elif l[i] < l[i-1]:
            if direction == 1:
                return False
            direction = -1
        else:
            # equal elements don't change direction
            continue
    return True


