def anti_shuffle(s):
    from re import finditer

    # Find all words and spaces with their spans
    parts = []
    last_end = 0
    for match in finditer(r'\S+|\s+', s):
        parts.append((match.group(), match.start(), match.end()))

    # Reconstruct the string with sorted words, spaces unchanged
    result = []
    for text, start, end in parts:
        if text.isspace():
            # keep spaces as is
            result.append(text)
        else:
            # sort characters in ascending ASCII order
            sorted_word = ''.join(sorted(text))
            result.append(sorted_word)
    return ''.join(result)


