def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        total = 0
        i = 0
        if s[0] == '-':
            total -= int(s[1])
            i = 2
        else:
            i = 0
        while i < len(s):
            total += int(s[i])
            i += 1
        return total

    return sorted(nums, key=lambda x: digit_sum(x))


