from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split(' ')
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
                if current_depth < 0:
                    # Unbalanced parentheses, reset to zero (or could raise error)
                    current_depth = 0
        result.append(max_depth)
    return result


