def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Find the index where the array "breaks" the non-decreasing order
    # Since elements are unique, we look for arr[i] > arr[i+1]
    break_points = 0
    break_index = -1
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            break_points += 1
            break_index = i
            if break_points > 1:
                return False

    # If no break points, array is already sorted
    if break_points == 0:
        return True

    # Check if the array can be rotated to be sorted:
    # The elements after break_index to the end and from start to break_index
    # should form a sorted array when rotated.
    # Specifically, check if arr[-1] <= arr[0] to ensure rotation is valid
    if arr[-1] > arr[0]:
        return False

    return True


