def parse_nested_parens(paren_string):
    """ Input to this function is a string. Output the deepest level of nesting of parentheses.
    Unmatched closing parentheses are ignored.
    """
    max_depth = 0
    current_depth = 0
    for ch in paren_string:
        if ch == '(':
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif ch == ')':
            if current_depth > 0:
                current_depth -= 1
