import string

def select_words(s: str, n: int) -> list[str]:
    vowels = set("aeiouAEIOU")
    consonants = set(string.ascii_letters) - vowels  # includes 'y' as consonant

    def clean_word(word: str) -> str:
        return ''.join(ch for ch in word if ch.isalpha())

    result = []
    for word in s.split():
        cleaned = clean_word(word)
        count_consonants = sum(ch in consonants for ch in cleaned)
        if count_consonants == n:
            result.append(word)
    return result


