def parse_nested_parens(s):
    groups = s.split()
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                if current_depth > 0:
                    current_depth -= 1
                # If there's a closing paren without an opening, just ignore
            else:
                # ignore any other characters
                pass
        result.append(max_depth)
    return result


