def decode_shift(s: str):
    """
    Takes an input that was processed before and does something to get it back or adjust it somehow.
    Decodes a string encoded by shifting lowercase letters by +5, shifting them back by -5.
    Leaves uppercase and non-alphabetic characters unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            result.append(chr(((ord(ch) - 5 - ord('a')) % 26) + ord('a')))
