def will_it_fly(q, w):
    if not q:
        return False
    try:
        # Check if q is iterable (but not a string)
        iter(q)
        if isinstance(q, (str, bytes)):
            # Treat strings as single weights (not iterable of weights)
            return bool(q) and q <= w
        # Check palindrome
        if list(q) != list(q)[::-1]:
            return False
        # Check sum within weight limit
        return sum(q) <= w
    except TypeError:
        # q is a single weight
        return bool(q) and q <= w


