def anti_shuffle(s: str) -> str:
    result = []
    i = 0
    while i < len(s):
        if s[i] == ' ':
            # preserve spaces as is
            result.append(' ')
            i += 1
        else:
            # accumulate a piece (consecutive non-space chars)
            start = i
            while i < len(s) and s[i] != ' ':
                i += 1
            piece = s[start:i]
            sorted_piece = ''.join(sorted(piece))
            result.append(sorted_piece)
    return ''.join(result)


