def order_by_points(numbers):
    def digit_sum(n):
        s = str(n)
        total = 0
        i = 0
        while i < len(s):
            if s[i] == '-':
                i += 1
                # next digit is negative
                if i < len(s) and s[i].isdigit():
                    total -= int(s[i])
                    i += 1
            else:
                total += int(s[i])
                i += 1
        return total
    return sorted(numbers, key=digit_sum)


