def circular_shift(x, shift):
    s = str(x)
    if shift < 0:
        shift = 0
    if s.startswith('-'):
        digits = s[1:]
        n = len(digits)
        if shift > n:
            # reverse entire string including minus
            return s[::-1]
        shift %= n
        if shift == 0:
            return s
        shifted = digits[-shift:] + digits[:-shift]
        return '-' + shifted
    else:
        n = len(s)
        if shift > n:
            return s[::-1]
        shift %= n
        if shift == 0:
            return s
        return s[-shift:] + s[:-shift]


