        if arr[i] > arr[i + 1]:
            breaks += 1
            break_index = i
            if breaks > 1:
                return False

    # If no break found, array is already sorted
    if breaks == 0:
        return True

    # Check if rotating the array so that element after break_index is first
    # results in a sorted array.
    # The rotation index would be break_index + 1
    rotated = arr[break_index + 1:] + arr[:break_index + 1]

    # Check if rotated array is sorted non-decreasing
    for i in range(n - 1):
        if rotated[i] > rotated[i + 1]:
            return False
    return True


