def select_words(s, n):
    vowels = set('aeiouAEIOU')
    if not s:
        return []
    words = s.split()
    result = []
    for word in words:
        # Consider only alphabetic characters (ignore punctuation)
        filtered = ''.join(ch for ch in word if ch.isalpha())
        # Count consonants (letters not in vowels, y always consonant)
        consonant_count = sum(1 for ch in filtered if ch.lower() not in vowels)
        if consonant_count == n:
            result.append(filtered)
    return result


