def triples_sum_to_zero(l: list):
    if len(l) < 3:
        return False

    # Condition: three elements are distinct (no repeated indices)
    # and they sum to zero.
    # We'll check all triplets.

    n = len(l)
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                if l[i] + l[j] + l[k] == 0:
                    return True
    return False


