def monotonic(l: list):
    if not l:
        return True
    nondecreasing = all(l[i] <= l[i+1] for i in range(len(l)-1))
    nonincreasing = all(l[i] >= l[i+1] for i in range(len(l)-1))
    return nondecreasing or nonincreasing


