import re

def anti_shuffle(s):
    def sort_word(word):
        letters = [c for c in word if c.isalpha()]
        letters.sort(reverse=True)
        # Rebuild word: replace letters in descending order, keep other chars at same position
        res = []
        idx = 0
        for c in word:
            if c.isalpha():
                res.append(letters[idx])
                idx += 1
            else:
                res.append(c)
