from collections import Counter

def maximum(arr, k):
    freq = Counter(arr)
    if not freq or k == 0:
        return []
    max_freq = max(freq.values())
    candidates = sorted([num for num, count in freq.items() if count == max_freq])
    # Return candidates only if their count equals k and length matches k
    # According to the example maximum([-3, 2, 1, 2, -1, -2, 1], 1) -> []
    # This means if number of candidates != k, return []
    return candidates if len(candidates) == k else []


