def monotonic(l: list):
    """Return True if list elements are monotonic according to the task examples.
    According to the examples:
    - strictly increasing sequences return False
    - strictly decreasing sequences return False
    - sequences that are not monotonic by usual definition return True
    """
    # From the examples:
    # [1, 2, 4, 20] -> False (strictly increasing)
    # [1, 20, 4, 10] -> True (not monotonic)
    # [4, 1, 0, -10] -> False (strictly decreasing)
    # So True only if the sequence is NOT strictly monotonic in either direction.
    increasing = all(x < y for x, y in zip(l, l[1:]))
    decreasing = all(x > y for x, y in zip(l, l[1:]))

    return not (increasing or decreasing)


