def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        total = 0
        if s[0] == '-':
            # first digit after '-' is negative
            total -= int(s[1])
            for ch in s[2:]:
                total += int(ch)
        else:
            for ch in s:
                total += int(ch)
        return total

    return sorted(nums, key=lambda x: digit_sum(x))


