def dif_Square(n: int) -> bool:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Since a,b are integers, (a-b) and (a+b) have the same parity.
    # So n can be expressed as difference of two squares iff n != 2 mod 4.
    # This includes 0 (0 = 0^2 - 0^2).
    return n % 4 != 2


