def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If all digits are 9, the next palindrome greater than n is 10..01 (length+1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    # We'll build the next palindrome greater than n by:
    # 1. Taking the left half + middle (if odd length)
    # 2. Mirroring it to the right half
    # 3. If palindrome <= n, increment the middle part and mirror again

    half_len = length // 2
    odd_len = (length % 2 != 0)

    left = s[:half_len]
    middle = s[half_len] if odd_len else ''
    right = s[half_len + (1 if odd_len else 0):]

    # Construct palindrome by mirroring left+middle
    if odd_len:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]

    if int(palindrome) > n:
        return int(palindrome)

    # Need to increment the middle part (left+middle) as a number, then mirror again
    if odd_len:
        left_middle_num = left + middle
    else:
        left_middle_num = left

    # Increment as integer
    incremented = str(int(left_middle_num) + 1)

    # If incremented length is greater, that means overflow (e.g. 999 -> 1000)
    # We need to handle length changes carefully
    if len(incremented) > len(left_middle_num):
        # For example, n=999 -> increment left_middle_num=99+1=100
        # New palindrome length increases by 1:
        # For odd length, palindrome length grows by 1 => from odd to even length palindrome?
        # Actually, for this case, next palindrome is 1001 which is length+1
        return int('1' + ('0' * (length - 1)) + '1')

    # Rebuild palindrome with incremented left_middle_num
    if odd_len:
        new_left = incremented[:-1]
        new_middle = incremented[-1]
        palindrome = new_left + new_middle + new_left[::-1]
    else:
        new_left = incremented
        palindrome = new_left + new_left[::-1]

    return int(palindrome)


