def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x]: number of sequences of length i starting at element x (1 <= x <= m)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: sequences of length 1, each element x is a sequence
    for x in range(1, m + 1):
        dp[1][x] = 1

    for length in range(2, n + 1):
        # For each element x, sum over all next elements y >= 2*x
        # To speed up, precompute suffix sums for dp[length-1]

        suffix_sum = [0] * (m + 2)  # one extra to avoid index error
        for x in range(m, 0, -1):
            suffix_sum[x] = suffix_sum[x + 1] + dp[length - 1][x]

        for x in range(1, m + 1):
            double_x = 2 * x
            if double_x > m:
                dp[length][x] = 0
            else:
                dp[length][x] = suffix_sum[double_x]

    return sum(dp[n][1:m + 1])


