from typing import Set

def permute_string(s: str) -> None:
    def backtrack(path: list, used: list, res: Set[str]) -> None:
        if len(path) == len(s):
            permutation = ''.join(path)
            if permutation not in res:
                res.add(permutation)
                print(permutation)
            return
        for i in range(len(s)):
            if used[i]:
                continue
            used[i] = True
            path.append(s[i])
            backtrack(path, used, res)
            path.pop()
            used[i] = False

    backtrack([], [False]*len(s), set())


