def lucky_num(n):
    # Start with a list of odd numbers (all lucky numbers are odd)
    nums = list(range(1, 2 * n * 10, 2))  # large enough range to get n lucky numbers

    idx = 1
    while idx < len(nums):
        step = nums[idx]
        if step > len(nums):
            break
        # Remove every step-th number from the list, counting from index step-1 (0-based)
        del nums[step - 1::step]
        idx += 1
        if len(nums) >= n:
            continue
        else:
            # If we have less numbers than needed, extend the list and repeat
            # But this is very rare with large initial range
            break

    return nums[:n]


