def dif_Square(n: int) -> bool:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b, y = a+b, then n = x*y with y > x >= 0 and x,y have same parity.
    # So n can be represented as difference of two squares iff n can be factored into two integers x,y of same parity.
    # Proof:
    # a = (x+y)/2, b = (y-x)/2 must be integers => x and y must be both even or both odd.
    # So check if n has at least one factor pair (x,y) with x<=y and x,y same parity.

    # Handle zero:
    # 0 = 0^2 - 0^2 => True
    if n == 0:
        return True

    # For negative n, just consider abs(n) and swap roles of a and b:
    # Since a^2 - b^2 = n => b^2 - a^2 = -n, so if n negative, check -n.
    abs_n = abs(n)

    # Iterate over factors up to sqrt(abs_n)
    from math import isqrt
    limit = isqrt(abs_n)
    for x in range(1, limit + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check parity
            if (x % 2) == (y % 2):
                return True
    return False


