def find_solution(a, b, n):
    def extended_gcd(aa, bb):
        if bb == 0:
            return aa, 1, 0
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return g, x, y

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return 'No solution'

    # scale the solution to n
    x0 *= n // g
    y0 *= n // g

    # a/g and b/g for parametric solutions
    a_div = a // g
    b_div = b // g

    # We want non-negative x
    # x = x0 + k * (b/g)
    # y = y0 - k * (a/g)
    # find k so that x >= 0 and y is integer (it always is)

    # To get x >= 0:
    # x0 + k * b_div >= 0 -> k >= -x0 / b_div if b_div > 0 else k <= -x0 / b_div
    # To keep y integer no problem (always integer for integer k)

    # Also, we want the first solution with non-negative x (smallest k satisfying x>=0)
    # Among multiple, any is acceptable by instructions

    # Compute k bounds
    # Because k is integer, take ceiling/floor appropriately

    # If b_div > 0:
    import math
    k_min = math.ceil(-x0 / b_div) if b_div != 0 else 0
    # Check if y is integer is always true, but we should ensure y >= 0? The instructions say only x>=0.

    # We'll try k = k_min, k_min + 1, ... until we find y integer (always true) and x,y integers (always true)
    # But also ensure y integer (always true), so just check y>=0? Instructions do not require y non-negative.

    # So only x >= 0 is required, y can be any integer.

    x_candidate = x0 + k_min * b_div
    y_candidate = y0 - k_min * a_div

    if x_candidate >= 0:
        return ('x = ', x_candidate, ', y = ', y_candidate)

    # If b_div == 0, then x = x0, no parametric change, check x0 >=0
    if b_div == 0:
        if x0 >= 0:
            return ('x = ', x0, ', y = ', y0)
        else:
            return 'No solution'

    # If first candidate not >= 0, try k_min + 1 up to some limit (to avoid infinite loop)
    # But usually one candidate should suffice. If not, try next few k's.
    for k in range(k_min + 1, k_min + 100):
        x_candidate = x0 + k * b_div
        y_candidate = y0 - k * a_div
        if x_candidate >= 0:
            return ('x = ', x_candidate, ', y = ', y_candidate)

    return 'No solution'


