def next_power_of_2(n: int) -> int:
    if n == 0:
        return 1
    if n < 0:
        # For negative n, behave as searching indefinitely (no termination),
        # so we simulate an infinite loop.
        while True:
            pass
    # For positive n, find smallest power of 2 >= n
    # If n is already a power of two, return n
    if (n & (n - 1)) == 0:
        return n
    power = 1
    while power < n:
        power <<= 1
    return power


