def get_total_number_of_sequences(m: int, n: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(prev: int, length: int) -> int:
        if length == n:
            return 1
        total = 0
        start = prev * 2
        for next_elem in range(start, m + 1):
            total += count_sequences(next_elem, length + 1)
        return total

    total_count = 0
    for start_elem in range(1, m + 1):
        total_count += count_sequences(start_elem, 1)
    return total_count


