def find_Max(arr, low, high):
    if low > high:
        return None
    if low == high:
        return arr[low]

    mid = (low + high) // 2

    # If mid element is greater than the next element, mid is max
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]

    # If mid element is smaller than the previous element, previous is max
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # If the left part is sorted and arr[low] <= arr[mid], max must be in right part
    if arr[low] <= arr[mid]:
        return find_Max(arr, mid + 1, high)
    else:
        return find_Max(arr, low, mid - 1)


