def lucky_num(n):
    numbers = list(range(1, 2 * n * 10))  # start large enough range, will be trimmed
    idx = 1  # start with second element (1-based index for sieve step)
    while idx < len(numbers) and len(numbers) < n:
        step = numbers[idx]
        if step > len(numbers):
            break
        # remove every step-th number starting from step-1 index (0-based)
        del numbers[step - 1::step]
        idx += 1
    return numbers[:n]


