def get_noOfways(n: int, m: int) -> int:
    if m != 2:
        return 0
    if n <= 0:
        return 0
    # dp[i] = number of ways to tile 2 x i board with 2 x 1 tiles
    dp = [0] * (n + 1)
    dp[0] = 1  # base case: 1 way to tile empty board
    dp[1] = 1  # base case: only vertical tile

    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]


