def compute_Last_Digit(a: int, b: int) -> int:
    low, high = min(a, b), max(a, b)
    if high == low:
        return 1  # factorial(a)/factorial(a) = 1, last digit 1

    last_digit = 1
    for i in range(low + 1, high + 1):
        last_digit = (last_digit * (i % 10)) % 10
        # If last_digit becomes 0, it will stay 0, so we can break early
        if last_digit == 0:
            break
    return last_digit


