def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # If all 9's, the next palindrome is 10..01 (length+1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def mirror_left_to_right(num_str):
        half = (len(num_str)) // 2
        if len(num_str) % 2 == 0:
            return num_str[:half] + num_str[:half][::-1]
        else:
            return num_str[:half+1] + num_str[:half][::-1]

    # Generate palindrome by mirroring left part
    palindrome = mirror_left_to_right(s)
    palindrome_int = int(palindrome)

    if palindrome_int > n:
        return palindrome_int

    # If palindrome <= n, increment the middle part and mirror again
    num_list = list(s)
    length = len(num_list)
    mid = length // 2

    # Determine left side indices depending on even/odd length
    left_end = mid - 1
    right_start = mid + 1 if length % 2 else mid

    # Increment the middle digit(s)
    # For odd length increment the middle digit
    # For even length increment the left middle digit(s)
    carry = 1
    if length % 2 == 1:
        # Odd length: increment middle digit
        middle_idx = mid
        new_digit = str((int(num_list[middle_idx]) + carry) % 10)
        carry = (int(num_list[middle_idx]) + carry) // 10
        num_list[middle_idx] = new_digit
        left = left_end
        right = right_start
    else:
        # Even length: increment left middle digit(s)
        left = left_end
        right = right_start
        # We'll handle the carry increment loop below

    # Propagate carry on the left side and mirror to right side
    while left >= 0 and carry > 0:
        new_digit = str((int(num_list[left]) + carry) % 10)
        carry = (int(num_list[left]) + carry) // 10
        num_list[left] = new_digit
        num_list[right] = new_digit
        left -= 1
        right += 1

    # If carry remains after processing left side (e.g. 999 -> 1001)
    if carry > 0:
        # This means all left side digits were 9 and got carried over
        # Result palindrome will be 1 followed by zeros and ending with 1
        return int('1' + ('0' * (length - 1)) + '1')

    # If no carry remains, mirror left to right for remaining digits
    while left >= 0:
        num_list[right] = num_list[left]
        left -= 1
        right += 1

    return int(''.join(num_list))


