def count(bools):
    if not bools:
        return 0
    cnt = 0
    prev_false = False
    for b in bools:
        if b:
            cnt += 1
            prev_false = False
        else:
            if prev_false:
                # False following another False counts as True
                cnt += 1
            prev_false = True
    return cnt


