def find_solution(a, b, n):
    from math import gcd

    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - (aa // bb) * y1
            return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None  # no solution

    # Scale the solution to n
    x0 *= n // g
    y0 *= n // g

    a_div = a // g
    b_div = b // g

    # We want non-negative x, y:
    # General solution:
    # x = x0 + k * (b/g)
    # y = y0 - k * (a/g)
    #
    # Find k so that both x,y >= 0:
    # x >= 0 => x0 + k * b_div >= 0 => k >= -x0 / b_div
    # y >= 0 => y0 - k * a_div >= 0 => k <= y0 / a_div
    #
    # So k must satisfy:
    # ceil(-x0 / b_div) <= k <= floor(y0 / a_div)

    from math import ceil, floor

    k_min = ceil(-x0 / b_div) if b_div != 0 else float('-inf')
    k_max = floor(y0 / a_div) if a_div != 0 else float('inf')

    if k_min > k_max:
        return None  # no non-negative solution

    # Any k in [k_min, k_max] works. Choose k that makes x,y minimal or just k_min:
    k = k_min

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0 or y < 0:
        return None

    return (x, y)


