def get_total_number_of_sequences(alphabet_size: int, sequence_length: int) -> int:
    # Since the user clarified that the function should count sequences satisfying the doubling adjacency rule,
    # not ignoring it, we implement the logic accordingly.

    # The doubling adjacency rule (from context) means:
    # For a sequence s of length n, for each i in [1..n-1], s[i] == 2 * s[i-1]

    # But since the exact rule was not restated here, we infer "doubling adjacency rule" means:
    # each element after the first is either double the previous element or not, but since "doubling adjacency" 
    # likely means s[i] = 2 * s[i-1], otherwise no sequence is valid.

    # Also, the alphabet is numbers from 1 to alphabet_size inclusive.

    # So sequences start at some value x in [1..alphabet_size]
    # Next value is 2*x if 2*x <= alphabet_size, else no next value is possible.
    # So sequences are chains where each next element is double the previous, capped by alphabet_size.

    # We want to count sequences of length sequence_length where each adjacent pair follows s[i] == 2*s[i-1].

    # Approach:
    # Use DP:
    # dp[pos][val] = number of sequences of length pos+1 that end with val.

    # Initialization: dp[0][val] = 1 for all val in [1..alphabet_size] (sequence of length 1).

    # Transition:
    # dp[pos][val] = dp[pos-1][val//2] if val is even and val//2 in [1..alphabet_size], else 0

    if sequence_length == 0:
        return 0
    if alphabet_size == 0:
        return 0

    dp = [0] * (alphabet_size + 1)
    for v in range(1, alphabet_size + 1):
        dp[v] = 1  # sequences of length 1

    for pos in range(1, sequence_length):
        new_dp = [0] * (alphabet_size + 1)
        for val in range(1, alphabet_size + 1):
            if val % 2 == 0:
                prev = val // 2
                if 1 <= prev <= alphabet_size:
                    new_dp[val] = dp[prev]
        dp = new_dp

    return sum(dp)


