def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 1
    for v in d.values():
        if isinstance(v, dict):
            max_depth = max(max_depth, 1 + dict_depth(v))
        elif isinstance(v, (list, tuple)):
            for item in v:
                if isinstance(item, dict):
                    max_depth = max(max_depth, 1 + dict_depth(item))
                elif isinstance(item, (list, tuple)):
                    # recursively check nested lists/tuples for dicts
                    # only increase depth if dict found inside
                    depth_in_nested = dict_depth_in_sequence(item)
                    if depth_in_nested > 0:
                        max_depth = max(max_depth, 1 + depth_in_nested)
    return max_depth

def dict_depth_in_sequence(seq):
    max_depth = 0
    for item in seq:
        if isinstance(item, dict):
            max_depth = max(max_depth, dict_depth(item))
        elif isinstance(item, (list, tuple)):
            depth = dict_depth_in_sequence(item)
            if depth > max_depth:
                max_depth = depth
    return max_depth


