def remove_column(matrix, col_idx):
    if not matrix:
        return []

    row_length = len(matrix[0])
    if not (0 <= col_idx < row_length):
        raise IndexError("Column index out of range")

    for row in matrix:
        if len(row) != row_length:
            raise ValueError("Rows have differing lengths before removal")

    new_row_length = row_length - 1
    new_matrix = []
    for row in matrix:
        new_row = row[:col_idx] + row[col_idx + 1:]
        if len(new_row) != new_row_length:
            raise ValueError("Rows have differing lengths after removal")
        new_matrix.append(new_row)

    return new_matrix


