def smallest_missing(arr, low, high):
    # Handle empty subarray or invalid indices gracefully
    if low > high or low < 0 or high >= len(arr):
        return low  # If invalid range, smallest missing is low by definition

    left, right = low, high
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == mid:
            left = mid + 1
        else:
            right = mid - 1
    return left


