from typing import List

def permute_string(s: str) -> List[str]:
    # This function returns all permutations of s including duplicates,
    # preserving duplicates explicitly (no skipping),
    # in a fixed deterministic order (sorted order of characters),
    # and returns all permutations including repeated ones.

    def backtrack(path, used):
        if len(path) == len(s):
            result.append("".join(path))
            return
        for i in range(len(s)):
            if used[i]:
                continue
            # We do NOT skip duplicates here because duplicates should be included fully.
            used[i] = True
            path.append(s[i])
            backtrack(path, used)
            path.pop()
            used[i] = False

    s = sorted(s)  # sort to get a deterministic order
    result = []
    used = [False] * len(s)
    backtrack([], used)
    return result


