def find_Max(arr):
    left, right = 0, len(arr) - 1
    # If array is not rotated (sorted ascending), max is last element
    if arr[left] < arr[right]:
        return arr[right]

    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than next element, mid is max
        if mid < right and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # If mid element is less than previous element, previous is max
        if mid > left and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        # Decide which half to choose
        if arr[mid] >= arr[left]:
            left = mid + 1
        else:
            right = mid - 1
    return arr[left]


