def lucky_num(n):
    # Generate lucky numbers using the sieve of lucky numbers method
    # Start with odd numbers from 1 upwards (1 is considered lucky)
    nums = list(range(1, 2 * n * 10, 2))  # initial large list to ensure enough lucky numbers
    idx = 1
    while idx < len(nums):
        step = nums[idx]
        if step > len(nums):
            break
        # Remove every step-th element from the list, starting from step-1 (0-based index)
        del nums[step - 1::step]
        idx += 1
        if len(nums) >= n:
            # We have at least n lucky numbers, can break early
            pass
    return nums[:n]


