def dif_Square(n: int) -> bool:
    # A number n can be represented as difference of squares a^2 - b^2
    # if and only if n is NOT congruent to 2 modulo 4.
    # Proof outline:
    # a^2 - b^2 = (a+b)(a-b)
    # For integers a,b, all integers n except those of the form 4k+2 can be represented.
    # So, return False if n % 4 == 2, else True.
    return n % 4 != 2


