def find_solution(a, b, n):
    if b == 0:
        # then ax = n => x = n/a if integer and non-negative
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return 'No solution'
    x = 0
    while True:
        remainder = n - a * x
        if remainder < 0:
            return 'No solution'
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1


