def find_Max(arr):
    low, high = 0, len(arr) - 1
    # If array is not rotated (sorted), the max is the last element
    if arr[low] < arr[high]:
        return arr[high]

    while low <= high:
        mid = (low + high) // 2
        # Check if mid is the maximum
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which half to choose for max
        if arr[mid] >= arr[low]:
            # max is in right half
            low = mid + 1
        else:
            # max is in left half
            high = mid - 1
    # Fallback (should not reach here if array is rotated sorted)
    return arr[0]


