def lucky_num(n):
    """
    Return the first n lucky numbers using the sieve of lucky numbers.
    """
    # Start with a list of odd numbers starting from 1 (1 is considered a lucky number)
    numbers = list(range(1, 2 * n * 10, 2))  # oversize list to ensure enough lucky numbers

    idx = 1  # start with the second element's value as the step (index 1, value 3)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list, starting from index step-1 (0-based)
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            # If we already have n or more lucky numbers, we can stop early
            break

    return numbers[:n]


