def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of two squares if and only if n is NOT congruent to 2 mod 4.
    # Proof outline:
    # Any square is congruent to 0 or 1 mod 4.
    # So difference of squares can be 0,1,3 mod 4 but never 2 mod 4.
    # Therefore, return False if n % 4 == 2, else True.
    return (n % 4) != 2


