def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # Next palindrome after 999...9 is 100...001
        return num + 2  # e.g. 9->11, 99->101, 999->1001

    # Make a palindrome by mirroring left half to right half
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    odd = (length % 2 != 0)
    left_half = s[: (length + 1) // 2]  # left half + middle if odd length
    # Construct palindrome from left_half
    pal = int(make_palindrome(left_half, odd))
    if pal > num:
        return pal

    # Increment the left half and mirror again
    # Convert left_half to int, add 1
    left_num = int(left_half) + 1
    left_str = str(left_num)
    # If increment caused length increase (e.g. 999 + 1 = 1000)
    if len(left_str) > len(left_half):
        # This means the palindrome length increases by 1 or 2 digits
        # For example, 999 -> 1000, length increased
        if odd:
            # For odd length, new palindrome length will be length+1
            return int('1' + ('0' * (length -1)) + '1')
        else:
            # Even length, palindrome length will be length+1
            return int('1' + ('0' * (length -1)) + '1')

    pal = int(make_palindrome(left_str, odd))
    return pal


