def find_solution(a: int, b: int, n: int):
    if a == 0 and b == 0:
        return "No solution" if n != 0 else ('x = ', 0, ', y = ', 0)

    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        gcd, s1, t1 = extended_gcd(y, x % y)
        s = t1
        t = s1 - (x // y) * t1
        return (gcd, s, t)

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        return "No solution"

    x = x0 * (n // gcd)
    y = y0 * (n // gcd)

    # Adjust sign if a or b was negative
    if a < 0:
        x = -x
    if b < 0:
        y = -y

    return ('x = ', x, ', y = ', y)


