        # For lists, remove the element at index if possible and recurse into each element
        new_list = []
        for item in data:
            if isinstance(item, list):
                # Remove the element at index if it exists
                if 0 <= index < len(item):
                    new_item = item[:index] + item[index+1:]
                else:
                    new_item = item[:]
                # Recurse into each element of the inner list in case of deeper nesting
                new_list.append(remove_column(new_item, index))
            else:
                # Recurse into non-list elements (dicts or others)
                new_list.append(remove_column(item, index))
        return new_list
    elif isinstance(data, dict):
        # For dicts, recurse into each value
        return {k: remove_column(v, index) for k, v in data.items()}
    else:
        # For other types, return as is
        return data


