def find_Max(arr, start, end):
    if start > end or start < 0 or end >= len(arr):
        return None
    if start == end:
        return arr[start]
    max_in_rest = find_Max(arr, start + 1, end)
    return arr[start] if arr[start] > max_in_rest else max_in_rest


