def lucky_num(n=10):
    numbers = list(range(1, 2*n*10))  # start with a large enough list
    idx = 1
    while len(numbers) < n or idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from step-1 index
        del numbers[step-1::step]
        idx += 1
        if idx >= len(numbers):
            break
        if len(numbers) >= n:
            break
    return numbers[:n]


