def dif_Square(n: int) -> bool:
    # A number n can be expressed as a² - b² = (a - b)(a + b) with a ≥ b ≥ 0.
    # Since a,b integers, both (a-b) and (a+b) are integers, and a≥b≥0 => a-b≥0, a+b≥0.
    # Let x = a-b and y = a+b, with x ≤ y, both ≥0 and integers.
    # Then n = x * y, with x ≤ y and both non-negative integers.
    # Also, since a=(x+y)/2 and b=(y-x)/2 must be integers, (x+y) and (y-x) must both be even,
    # i.e., x and y have the same parity.
    #
    # So n can be expressed as difference of squares iff n can be factorized as n = x * y,
    # with x,y ≥ 0, x ≤ y, x and y have same parity.
    #
    # Also, since b≥0, a≥b => a≥0, so a,b≥0.
    #
    # Special cases:
    # If n=0, then a² - a²=0 is valid, so True.
    # For negative n, check if -n can be represented as difference of squares with a≥b≥0
    # but since a² - b² ≥0 for a,b≥0 with a≥b, negative n cannot be represented.
    # So if n<0, return False.
    #
    # So only n≥0 need be checked.

    if n < 0:
        return False
    if n == 0:
        return True  # 0 = 0² - 0²

    # Try all x from 1 to int(sqrt(n))
    # For each x dividing n, y = n//x
    # Check parity and x ≤ y
    import math
    limit = int(math.isqrt(n))
    for x in range(1, limit + 1):
        if n % x == 0:
            y = n // x
            if x <= y and (x % 2) == (y % 2):
                # (x,y) valid factor pair
                # a = (x + y)//2, b = (y - x)//2, both integers and b≥0 since y≥x
                # a≥b≥0 guaranteed by construction
                return True
    return False


