def find_solution(a, b, n):
    x = 0
    while True:
        remainder = n - a * x
        if remainder < 0:
            break
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
        elif b == 0:
            if remainder == 0:
                return ('x = ', x, ', y = ', 0)
        x += 1
    return 'No solution'


