def get_total_number_of_sequences(start: int, end: int, step: int) -> int:
    """
    Counts the number of strictly increasing sequences (length >=1) that can be formed 
    from the arithmetic progression: start, start+step, start+2*step, ..., up to end,
    where the difference between consecutive elements is at least 'step'.

    Since the sequence elements are from an arithmetic progression with difference 'step',
    any strictly increasing sequence corresponds to choosing any non-empty subset of these elements
    in ascending order. The minimal difference condition is naturally satisfied.

    The count is thus 2^n - 1, where n is the number of elements in the progression.
    """
    if step <= 0 or start > end:
        return 0  # no valid sequences if step non-positive or range invalid

    n = ((end - start) // step) + 1  # number of elements in the arithmetic progression
    return (1 << n) - 1  # 2^n -1


