import re

def text_match_two_three(s: str, first_char: str, repeat_char: str) -> bool:
    """
    Check if the string contains a substring starting with first_char followed by 
    1 to 3 repetitions of repeat_char.

    Example:
    text_match_two_three('axxxb', 'a', 'x') -> True (matches 'axxx')
    text_match_two_three('abbb', 'a', 'b') -> True (matches 'abbb')
    text_match_two_three('axbbbb', 'a', 'b') -> True (matches 'abbb' part of 'axbbbb')
    text_match_two_three('ab', 'a', 'b') -> True (matches 'ab')
    text_match_two_three('accc', 'a', 'b') -> False (no 'ab...' pattern)
    """
    pattern = re.compile(re.escape(first_char) + re.escape(repeat_char) + '{1,3}')
    return bool(pattern.search(s))


