def remove_column(collection, position):
    result = []
    for inner_list in collection:
        if not isinstance(inner_list, list):
            # If inner_list is not a list, just append it as is
            result.append(inner_list)
            continue
        new_inner = []
        for sublist in inner_list:
            if isinstance(sublist, list) and 0 <= position < len(sublist):
                new_sublist = sublist[:position] + sublist[position+1:]
            else:
                new_sublist = sublist
            new_inner.append(new_sublist)
        result.append(new_inner)
    return result


