from typing import List, Tuple, Union

def repeat_tuples(items: List[Tuple], times: int) -> Union[List[Tuple], Tuple[Tuple]]:
    result = items * times
    # Return the same type as the input collection: list if input is list, tuple if input is tuple
    # Since input is specified as list of tuples, return list of tuples
    return result


