import re

def str_to_tuple(number_str: str, from_sep: str, to_sep: str) -> str:
    """
    Convert a grouped number string from one grouping separator to another.

    Args:
        number_str (str): The input number string with group separators.
        from_sep (str): The current grouping separator in the input string.
        to_sep (str): The desired grouping separator in the output string.

    Returns:
        str: The number string reformatted with the new grouping separator.
    """
    # Remove all from_sep characters
    # Handle special cases where from_sep or to_sep might be empty or space
    # First, remove any from_sep characters from the string
    # Then, re-insert grouping separators appropriately (every 3 digits from right)

    # Strip spaces from ends
    s = number_str.strip()

    # Remove all from_sep characters
    if from_sep:
        # Escape from_sep if it's a special regex char
        esc_from_sep = re.escape(from_sep)
        s = re.sub(esc_from_sep, '', s)
    else:
        # If from_sep is empty string, no separators to remove
        pass

    # Remove any spaces that might remain if from_sep was space and not targeted
    # Actually, assume only from_sep is the grouping separator to remove.

    # Now s should be digits (possibly with leading sign or decimal part?)
    # The task is ambiguous about decimals and signs.
    # To be safe, handle optional leading sign and optional decimal part:

    # Match optional sign, digits (integer), optional decimal part
    m = re.match(r'^([+-]?)(\d+)(\.\d+)?$', s)
    if not m:
        # If input doesn't match this pattern, return it unchanged (or raise?)
        # Task ambiguity: choose to return input unchanged
        return number_str

    sign, int_part, dec_part = m.groups()
    dec_part = dec_part or ''

    # Insert the to_sep every 3 digits from right in int_part
    # If to_sep is empty, just return digits without separator
    if not to_sep:
        grouped_int = int_part
    else:
        # Reverse int_part to process from right to left
        rev = int_part[::-1]
        groups = [rev[i:i+3] for i in range(0, len(rev), 3)]
        grouped_int = to_sep.join(g[::-1] for g in groups[::-1])

    return f"{sign}{grouped_int}{dec_part}"


