def lucky_num(n):
    # Start with a list of odd numbers starting from 1, large enough to get n lucky numbers
    numbers = list(range(1, 10 * n * 10, 2))
    idx = 1  # start from second element (index 1)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number, counting from 1, starting at index step-1
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n and idx > n:
            break
    return numbers[:n]


