def dif_Square(n: int) -> bool:
    # A number n can be represented as a difference of two squares (a^2 - b^2)
    # if and only if n is not congruent to 2 mod 4.
    # Explanation:
    # a^2 - b^2 = (a+b)(a-b)
    # Both (a+b) and (a-b) are integers.
    # Since (a+b) and (a-b) have the same parity (both even or both odd),
    # their product is never congruent to 2 mod 4.
    # Thus, any integer n except those congruent to 2 mod 4 can be represented as difference of two squares.

    return n % 4 != 2


