def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, s, t = extended_gcd(y, x % y)
        return g, t, s - (x // y) * t

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None

    # Scale the initial solution
    x0 *= n // g
    y0 *= n // g

    a_div = a // g
    b_div = b // g

    # We want to find k such that:
    # x = x0 + k * (b/g) >= 0
    # y = y0 - k * (a/g) >= 0
    #
    # So:
    # k >= -x0 / (b/g)
    # k <= y0 / (a/g)

    from math import ceil, floor

    k_min = ceil(-x0 / b_div) if b_div != 0 else float('-inf')
    k_max = floor(y0 / a_div) if a_div != 0 else float('inf')

    if k_min > k_max:
        return None

    # Any k in [k_min, k_max] works; choose k = k_min to get nonnegative x and y
    k = k_min

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x >= 0 and y >= 0:
        return (x, y)
    else:
        return None


