def find_Max(arr):
    if not arr:
        return None
    low, high = 0, len(arr) - 1
    # If the array is not rotated (strictly ascending)
    if arr[low] < arr[high]:
        return arr[high]
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid
    # low is now the index of the smallest element
    # max element is just before it
    return arr[low - 1]


