def lucky_num(n):
    # The sieve of lucky numbers:
    # Start with the list of odd numbers starting from 1
    numbers = list(range(1, 2 * n * 10, 2))  # overshoot to ensure enough lucky numbers
    idx = 1  # start from the second element (index=1), which will be the first step in sieve

    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list (1-based indexing)
        # Note: removing every step-th number means removing numbers at indices:
        # step-1, 2*step-1, 3*step-1, ... but since list is 0-based indexed and we start counting from 1,
        # we remove numbers at indices step-1, 2*step-1, 3*step-1, etc.
        del numbers[step-1::step]
        idx += 1

    return numbers[:n]


