def get_noOfways(n: int, m: int) -> int:
    if m != 2:
        # According to the specification, only 2 x n boards are handled
        return 0
    if n == 0:
        return 1
    if n == 1:
        return 1
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]


